with deduped as (select id, full_name, email, dept_id, manager_id, job_title, salary, level from (select *, row_number() over (partition by manager_id order by salary desc, id) as rn from employees) ranked where rn = 1) select dept_id, approx_percentile(salary, array(0.25, 0.5, 0.75)) as salary_quartiles, count(case when job_title = 'Analyst' then 1 end) as analyst_count, count(case when job_title = 'Analyst' then 1 end) as analyst_count_2 from deduped group by dept_id;
